function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 100 : int(2, 8);
  const odd = () => 2 * int(0, 49) + 1;
  const even = () => 2 * int(1, 50);
  // 0: any values, 1: all odd, 2: exactly one even, 3: exactly two evens.
  const mode = int(0, 3);
  const nums = Array.from({ length: n }, () => (mode === 0 ? int(1, 100) : odd()));
  const evens = mode === 2 ? 1 : mode === 3 ? 2 : 0;
  const spots = Array.from({ length: n }, (_, i) => i);
  for (let k = 0; k < evens; k++) {
    const pick = int(k, n - 1);
    [spots[k], spots[pick]] = [spots[pick], spots[k]];
    nums[spots[k]] = even();
  }
  return [nums];
}
